/**
 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
 * builds one fully-populated tenant (org, four members, a project) through the
 * real repositories, so the rows under test are the rows production writes.
 *
 * Kept apart from `tests/helpers/*` — those belong to another owner.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}
/**
 * Test double for `@/lib/id` (owner E).
 *
 * The server suite needs ids that are valid ULIDs *and* reproducible, so a
 * failing assertion names the same row on every run. Counter-based rather than
 * random for exactly that reason.
 */
const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const ULID_LENGTH = 26;

let counter = 0;

export function newId(): string {
  counter += 1;
  return encode(counter);
}

export function isUlid(value: string): boolean {
  return (
    value.length === ULID_LENGTH &&
    [...value].every((char) => ULID_ALPHABET.includes(char.toUpperCase()))
  );
}

export function idFactory(seed: number): () => string {
  let local = seed;
  return () => {
    local += 1;
    return encode(local);
  };
}

/** Test-only: rewinds the counter so each file starts from the same ids. */
export function resetIds(): void {
  counter = 0;
}

function encode(value: number): string {
  let remaining = value;
  let out = "";

  while (out.length < ULID_LENGTH) {
    out = `${ULID_ALPHABET[remaining % 32] ?? "0"}${out}`;
    remaining = Math.floor(remaining / 32);
  }

  return out.slice(-ULID_LENGTH);
}
/**
 * Test doubles for the `src/lib` helpers owned by E.
 *
 * The server layer legitimately depends on them, but they are still stubs at
 * the time this suite runs, so each is replaced with the smallest faithful
 * implementation the assertions need. Swap-in only — no server code is mocked.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { IsoTimestamp, OrgId } from "@/types/common";

/* -------------------------------------------------------------- @/lib/hash */

export const hashModule = {
  hashPassword: async (password: string): Promise<string> =>
    `scrypt$${password.length}$${simpleHash(password)}`,
  verifyPassword: async (password: string, hash: string): Promise<boolean> =>
    (await hashModule.hashPassword(password)) === hash,
  hashToken: (token: string): string => `sha256$${simpleHash(token)}`,
  randomToken: (bytes = 32): string =>
    `t${simpleHash(String(tokenCounter++))}`.padEnd(bytes, "x"),
};

let tokenCounter = 1;

/* -------------------------------------------------------- @/lib/rate-limit */

/** Verdicts the suite can steer: the default is "always allowed". */
export const rateLimitState = { allowed: true, remaining: 100 };

export const rateLimitModule = {
  consumeRateLimit: async (
    _orgId: OrgId,
    _bucketKey: string,
    cost = 1,
  ): Promise<{
    allowed: boolean;
    remaining: number;
    resetAt: IsoTimestamp;
  }> => ({
    allowed: rateLimitState.allowed,
    remaining: Math.max(0, rateLimitState.remaining - cost),
    resetAt: new Date(Date.now() + 60_000).toISOString() as IsoTimestamp,
  }),
  getBucketConfig: () => ({ capacity: 100, refillPerMinute: 100 }),
  RATE_LIMIT_BUCKETS: {} as Readonly<
    Record<string, { capacity: number; refillPerMinute: number }>
  >,
};

/* ---------------------------------------------------------- @/lib/mentions */

export const mentionsModule = {
  extractMentions: (body: string): readonly string[] =>
    [...body.matchAll(/@([\w.-]+)/g)].map((match) => match[1] ?? ""),
  resolveMentions: (
    body: string,
    members: readonly MemberWithUser[],
  ): readonly UserId[] => {
    const handles = new Set(
      mentionsModule.extractMentions(body).map((handle) => handle.toLowerCase()),
    );
    return members
      .filter(
        (member) =>
          handles.has(member.user.name.toLowerCase()) ||
          handles.has(member.user.email.split("@")[0]?.toLowerCase() ?? ""),
      )
      .map((member) => member.userId);
  },
  highlightMentions: (body: string): string =>
    body.replace(/@([\w.-]+)/g, "<b>@$1</b>"),
};

/* ------------------------------------------------------------ @/lib/logger */

export const loggerModule = {
  createLogger: () => ({
    debug: () => undefined,
    info: () => undefined,
    warn: () => undefined,
    error: () => undefined,
  }),
};

/* --------------------------------------------------------------- @/lib/csv */

export const csvModule = {
  toCsv: (
    rows: readonly Readonly<
      Record<string, string | number | boolean | null>
    >[],
    columns: readonly string[],
  ): string =>
    [
      columns.join(","),
      ...rows.map((row) =>
        columns.map((column) => csvModule.escapeCsvValue(row[column] ?? null)).join(","),
      ),
    ].join("\n"),
  escapeCsvValue: (value: string | number | boolean | null): string => {
    const text = value === null ? "" : String(value);
    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
  },
  csvResponseHeaders: (filename: string) => ({
    "content-type": "text/csv",
    "content-disposition": `attachment; filename="${filename}"`,
  }),
};

function simpleHash(value: string): string {
  let hash = 2_166_136_261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash).toString(36);
}
/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}
/**
 * Plan-limit enforcement on the write paths.
 *
 * `PLAN_LIMITS` is the single source of the numbers and `wouldExceedLimit()`
 * the single comparison; these cases prove the services actually consult them
 * before writing, and that a pending invitation already holds its seat.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
// The only double left in this suite. `@/lib/rate-limit` is real everywhere
// else, but these cases need to *choose* the verdict — the seat-quota refusal
// has to be provably about seats and not about a bucket the previous case
// happened to drain, and the throttling case needs a guaranteed denial.
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import { getPlanLimits } from "@/config/plan-limits";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as projectService from "@/server/services/project-service";
import * as usageService from "@/server/services/usage-service";
import { rateLimitState } from "./_support/doubles/misc";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
/** Free plan: 3 seats, 2 projects. The fixture seeds four members. */
let free: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  free = await createTenant("frugal", "free");
  growth = await createTenant("growing", "growth");
});

afterAll(() => {
  cleanup();
  rateLimitState.allowed = true;
});

describe("seat quota on invite", () => {
  it("rejects an invite once the plan's seats are taken", async () => {
    expect(getPlanLimits("free").seats).toBe(3);
    await expect(memberRepo.countActiveMembers(free.org.id)).resolves.toBe(4);

    await expect(
      invitationService.inviteMember(free.actors.owner, {
        orgId: free.org.id,
        email: "fifth@frugal.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/i);
  });

  it("writes no invitation row when the quota rejects the batch", async () => {
    await expect(
      invitationRepo.countPendingInvitations(free.org.id),
    ).resolves.toBe(0);
  });

  it("rejects a bulk invite as a whole rather than partially filling it", async () => {
    const limits = getPlanLimits("growth");
    expect(limits.seats).toBe(50);

    const invites = Array.from({ length: 49 }, (_, index) => ({
      email: `bulk-${index}@growing.test`,
      role: "member" as const,
    }));

    await expect(
      invitationService.inviteMembers(growth.actors.owner, {
        orgId: growth.org.id,
        invites,
      }),
    ).rejects.toThrow(/seats/i);

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(0);
  });

  it("counts a pending invitation against the seat quota", async () => {
    const before = await invitationRepo.countPendingInvitations(growth.org.id);

    await invitationService.inviteMember(growth.actors.owner, {
      orgId: growth.org.id,
      email: "solo@growing.test",
      role: "member",
    });

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(before + 1);
  });

  it("refuses the invite when the rate limiter says no", async () => {
    rateLimitState.allowed = false;

    await expect(
      invitationService.inviteMember(growth.actors.owner, {
        orgId: growth.org.id,
        email: "throttled@growing.test",
        role: "member",
      }),
    ).rejects.toThrow(/rate limit/i);

    rateLimitState.allowed = true;
  });
});

describe("project quota", () => {
  it("rejects the project that would exceed the plan", async () => {
    expect(getPlanLimits("free").projects).toBe(2);

    // The fixture already created one project; this fills the plan.
    await projectService.createProject(free.actors.owner, {
      orgId: free.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await expect(
      projectService.createProject(free.actors.owner, {
        orgId: free.org.id,
        name: "Third",
        slug: "third",
        key: "THR",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      }),
    ).rejects.toThrow(/projects/i);
  });
});

describe("BillingService.checkLimit", () => {
  it("reports the plan, the usage and whether one more would breach", async () => {
    await usageService.recomputeUsage(free.org.id);

    const check = await billingService.checkLimit(free.org.id, "seats");

    expect(check).toMatchObject({
      resource: "seats",
      plan: "free",
      limit: 3,
      used: 4,
      remaining: 0,
      exceeded: true,
    });
  });

  it("leaves an org with room under its limit", async () => {
    await usageService.recomputeUsage(growth.org.id);

    const check = await billingService.checkLimit(growth.org.id, "seats");
    expect(check.exceeded).toBe(false);
    expect(check.remaining).toBeGreaterThan(0);
  });
});
/** Domain-error to `AppErrorShape` mapping for every error class. */
import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  HTTP_STATUS_BY_CODE,
  fieldErrorsFromZod,
  isDomainError,
  toActionResult,
  toAppError,
} from "@/lib/errors";
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError, explain } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { OrgId } from "@/types/common";
import { makeActor, ORG_A, ORG_B } from "../helpers/factories";

const schema = z.object({
  title: z.string().min(3),
  estimate: z.number().int(),
});

function permissionError(): PermissionDeniedError {
  const actor = makeActor({ role: "viewer" });
  const resource = { kind: "organization", orgId: ORG_A } as const;
  return new PermissionDeniedError("org:delete", explain(actor, "org:delete", resource));
}

describe("lib/errors", () => {
  it("maps a permission denial to `forbidden` with the decision in meta", () => {
    const shape = toAppError(permissionError());
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.action).toBe("org:delete");
    expect(shape.meta?.reason).toBe("denied_by_role");
  });

  it("maps a tenant scope violation to `tenant_scope_violation`", () => {
    const shape = toAppError(new TenantScopeError(ORG_A, ORG_B));
    expect(shape.code).toBe("tenant_scope_violation");
    expect(shape.meta?.expectedOrgId).toBe(ORG_A);
    expect(shape.message).not.toContain(ORG_B as string);
  });

  it("maps a disabled feature to `forbidden` and names the flag", () => {
    const shape = toAppError(new FeatureDisabledError("webhooks"));
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.flag).toBe("webhooks");
  });

  it("maps double archiving to `conflict`", () => {
    const shape = toAppError(new AlreadyArchivedError("Issue", "01ISS"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.entity).toBe("Issue");
  });

  it("maps an invalid slug to `validation_failed` with a slug field error", () => {
    const shape = toAppError(new InvalidSlugError("Admin!", "is reserved"));
    expect(shape.code).toBe("validation_failed");
    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
  });

  it("maps a ZodError to field errors keyed by dotted path", () => {
    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
    expect(parsed.success).toBe(false);
    if (parsed.success) return;

    const fields = fieldErrorsFromZod(parsed.error);
    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
    expect(toAppError(parsed.error).code).toBe("validation_failed");
  });

  it("falls back to `internal_error` for an unknown throw", () => {
    expect(toAppError(new Error("boom")).code).toBe("internal_error");
    expect(toAppError("boom").code).toBe("internal_error");
    expect(toAppError("boom").message).toContain("Something went wrong");
  });

  it("recognises exactly the domain error classes", () => {
    expect(isDomainError(permissionError())).toBe(true);
    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
    expect(isDomainError(new Error("boom"))).toBe(false);
    expect(isDomainError(null)).toBe(false);
  });

  it("gives every error code an HTTP status", () => {
    for (const [code, status] of Object.entries(HTTP_STATUS_BY_CODE)) {
      expect(status, code).toBeGreaterThanOrEqual(400);
    }
    expect(HTTP_STATUS_BY_CODE.rate_limited).toBe(429);
    expect(HTTP_STATUS_BY_CODE.plan_limit_exceeded).toBe(402);
  });

  it("wraps a failure as an ActionResult, never throwing", () => {
    const result = toActionResult(new AlreadyArchivedError("Project", "01PRJ"));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("conflict");
    expect(typeof result.submittedAt).toBe("string");
  });

  it("keeps a cross-tenant org id out of the user-facing message", () => {
    const other = "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId;
