def sub(path, old, new, count=1):
    p = pathlib.Path(path)
    s = p.read_text()
    assert s.count(old) >= 1, (path, old)
    if count == 1:
        assert s.count(old) == 1, (path, old, s.count(old))
    p.write_text(s.replace(old, new))

