/**
 * Account creation as specified by `docs/adr/0003-account-creation.md`: slug
 * derivation that never refuses a name, case-insensitive addresses, the
 * duplicate-address conflict, the sign-up throttle and the workspace name.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

const { consumeRateLimit, verdict, sentEmails } = vi.hoisted(() => {
  const verdict = { allowed: true };
  return {
    verdict,
    sentEmails: [] as { to: unknown; subject: unknown }[],
    consumeRateLimit: vi.fn(async (..._args: unknown[]) => ({
      allowed: verdict.allowed,
      remaining: verdict.allowed ? 10 : 0,
      resetAt: new Date(Date.now() + 60_000).toISOString(),
    })),
  };
});

vi.mock("@/lib/rate-limit", () => ({ consumeRateLimit }));
vi.mock("@/lib/logger", () => ({
  createLogger: () => ({
    debug: () => undefined,
    warn: () => undefined,
    error: () => undefined,
    info: (message: string, fields: { to?: unknown; subject?: unknown } = {}) => {
      if (message === "email.sent") {
        sentEmails.push({ to: fields.to, subject: fields.subject });
      }
    },
  }),
}));

import { EmailTakenError, RateLimitedError, toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { isReservedSlug, isValidSlug } from "@/lib/slug";
import { createOrganizationSchema } from "@/schemas/organization";
import { getDb, users } from "@/server/db";
import * as memberRepo from "@/server/repositories/member-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as authService from "@/server/services/auth-service";
import { useTemporaryDatabase } from "../server/_support/fixtures";
import type { RegisterInput } from "@/schemas/auth";

const PASSWORD = "Correct-Horse-9-Battery";

function signUp(name: string, email: string): RegisterInput {
  return {
    name,
    email,
    password: PASSWORD,
    confirmPassword: PASSWORD,
    acceptTerms: true,
  };
}

function countUsers(): number {
  return getDb().select().from(users).all().length;
}

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  verdict.allowed = true;
  consumeRateLimit.mockClear();
  sentEmails.length = 0;
});

describe("services/auth-service — sign-up", () => {
  it("creates the user, a Free workspace and the owner membership in one step", async () => {
    const joined: string[] = [];
    const off = subscribe("member.joined", async (payload) => {
      joined.push(`${payload.userId}:${payload.role}`);
    });

    const { user, org } = await authService.register(
      signUp("Grace Hopper", "grace@one-step.test"),
    );
    off();

    expect(org.name).toBe("Grace Hopper's workspace");
    expect(org.slug).toBe("grace-hopper");
    expect(org.plan).toBe("free");
    expect(org.trialEndsAt).toBeNull();
    expect(org.ownerId).toBe(user.id);

    const member = await memberRepo.findMember(org.id, user.id);
    expect(member?.role).toBe("owner");
    expect(joined).toEqual([`${user.id}:owner`]);

    const subscription = await subscriptionRepo.findSubscription(org.id);
    expect(subscription).toMatchObject({ plan: "free", status: "active" });

    expect(sentEmails).toHaveLength(1);
    expect(sentEmails[0]?.to).toBe("grace@one-step.test");
    expect(String(sentEmails[0]?.subject)).toContain(org.name);
  });

  it.each([
    ["Admin", "admin-2"],
    ["Billing", "billing-2"],
    ["Support", "support-2"],
    ["Taskflow", "taskflow-2"],
    ["Al", "al"],
    ["J", "workspace"],
    ["山田", "workspace-2"],
    ["!!!", "workspace-3"],
  ])("signs up %s like anyone else", async (name, slug) => {
    const { user, org } = await authService.register(
      signUp(name, `person-${slug}@names.test`),
    );

    expect(org.slug).toBe(slug);
    expect(isValidSlug(org.slug)).toBe(true);
    expect(isReservedSlug(org.slug)).toBe(false);
    expect(org.name).toBe(`${name}'s workspace`);
    await expect(memberRepo.findMember(org.id, user.id)).resolves.toMatchObject({
      role: "owner",
    });
  });

  it("suffixes the derived slug when it is taken, however long it is", async () => {
    const name = "Wolfe Schlegel Steinhausen Bergerdorff ".repeat(2);
    const slugs: string[] = [];
    for (let attempt = 0; attempt < 4; attempt += 1) {
      const { org } = await authService.register(
        signUp(name, `long-${attempt}@names.test`),
      );
      slugs.push(org.slug);
    }

    expect(new Set(slugs).size).toBe(4);
    for (const slug of slugs) expect(isValidSlug(slug), slug).toBe(true);
  });

  it("shortens a long display name so the workspace name still fits and keeps its suffix", async () => {
    const name = "N".repeat(80);
    const { user, org } = await authService.register(
      signUp(name, "long-name@names.test"),
    );

    expect(user.name).toBe(name);
    expect(org.name).toBe(`${"N".repeat(52)}'s workspace`);
    expect(
      createOrganizationSchema.shape.name.safeParse(org.name).success,
    ).toBe(true);
  });

  it("never cuts a display name in the middle of a character", async () => {
    const { org } = await authService.register(
      signUp("😀".repeat(40), "emoji@names.test"),
    );

    expect(org.name).toBe(`${"😀".repeat(26)}'s workspace`);
    expect(org.name.length).toBeLessThanOrEqual(64);
  });
});

describe("services/auth-service — email addresses", () => {
  it("stores the address lowercased and signs in with any spelling", async () => {
    const { user } = await authService.register(
      signUp("Alice", "Alice@Example.com"),
    );
    expect(user.email).toBe("alice@example.com");
    expect(sentEmails[0]?.to).toBe("alice@example.com");

    for (const email of ["alice@example.com", "ALICE@EXAMPLE.COM", "Alice@Example.com"]) {
      const session = await authService.login({
        email,
        password: PASSWORD,
        rememberMe: false,
      });
      expect(session.user.id).toBe(user.id);
    }
  });

  it("refuses an address that already has an account as a conflict and creates nothing", async () => {
    const before = countUsers();

    for (const email of ["alice@example.com", "ALICE@example.COM"]) {
      const attempt = authService.register(signUp("Other Alice", email));
      await expect(attempt).rejects.toBeInstanceOf(EmailTakenError);
      expect(toAppError(await attempt.catch((error: unknown) => error)).code).toBe(
        "conflict",
      );
    }

    expect(countUsers()).toBe(before);
    expect(sentEmails).toHaveLength(0);
  });

  it("matches an account whose address was stored with capitals", async () => {
    const stamp = new Date().toISOString();
    getDb()
      .insert(users)
      .values({
        id: "01LEGACYLEGACYLEGACYLEGACY",
        email: "Legacy@Example.com",
        name: "Legacy",
        passwordHash: "seed",
        timezone: "UTC",
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    await expect(
      userRepo.findUserByEmail("legacy@example.com"),
    ).resolves.toMatchObject({ id: "01LEGACYLEGACYLEGACYLEGACY" });
    await expect(
      authService.register(signUp("Legacy", "legacy@example.com")),
    ).rejects.toBeInstanceOf(EmailTakenError);
  });
});

describe("services/auth-service — throttling", () => {
  it("charges the anonymous auth:register bucket once per sign-up attempt", async () => {
    await authService.register(signUp("Charged Once", "once@throttle.test"));

    expect(consumeRateLimit).toHaveBeenCalledTimes(1);
    expect(consumeRateLimit.mock.calls[0]?.[1]).toBe("auth:register");
  });

  it("refuses a throttled sign-up as rate_limited before anything is written", async () => {
    verdict.allowed = false;
    const before = countUsers();

    const error = await authService
      .register(signUp("Flood", "flood@throttle.test"))
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(RateLimitedError);
    expect(toAppError(error).code).toBe("rate_limited");
    expect(countUsers()).toBe(before);
    await expect(userRepo.findUserByEmail("flood@throttle.test")).resolves.toBeNull();
  });

  it("refuses a throttled sign-in and reset confirmation as rate_limited", async () => {
    verdict.allowed = false;

    const signIn = await authService
      .login({ email: "alice@example.com", password: PASSWORD, rememberMe: false })
      .catch((caught: unknown) => caught);
    expect(toAppError(signIn).code).toBe("rate_limited");

    const confirm = await authService
      .confirmPasswordReset({
        token: "t".repeat(32),
        password: PASSWORD,
        confirmPassword: PASSWORD,
      })
      .catch((caught: unknown) => caught);
    expect(toAppError(confirm).code).toBe("rate_limited");
  });

  it("keeps a throttled password-reset request silent", async () => {
    verdict.allowed = false;

    await expect(
      authService.requestPasswordReset({ email: "alice@example.com" }),
    ).resolves.toBeUndefined();
    expect(sentEmails).toHaveLength(0);
  });
});

