describe("services/auth-service — throttling", () => {
  it("charges the anonymous auth:register bucket once per sign-up attempt", async () => {
    await authService.register(signUp("Charged Once", "once@throttle.test"));

    expect(consumeRateLimit).toHaveBeenCalledTimes(1);
    expect(consumeRateLimit.mock.calls[0]?.[1]).toBe("auth:register");
  });

  it("refuses a throttled sign-up as rate_limited before anything is written", async () => {
    verdict.allowed = false;
    const before = countUsers();

    const error = await authService
      .register(signUp("Flood", "flood@throttle.test"))
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(RateLimitedError);
    expect(toAppError(error).code).toBe("rate_limited");
    expect(countUsers()).toBe(before);
    await expect(userRepo.findUserByEmail("flood@throttle.test")).resolves.toBeNull();
  });

  it("refuses a throttled sign-in and reset confirmation as rate_limited", async () => {
    verdict.allowed = false;

    const signIn = await authService
      .login({ email: "alice@example.com", password: PASSWORD, rememberMe: false })
      .catch((caught: unknown) => caught);
    expect(toAppError(signIn).code).toBe("rate_limited");

    const confirm = await authService
      .confirmPasswordReset({
        token: "t".repeat(32),
        password: PASSWORD,
        confirmPassword: PASSWORD,
      })
      .catch((caught: unknown) => caught);
    expect(toAppError(confirm).code).toBe("rate_limited");
  });

  it("keeps a throttled password-reset request silent", async () => {
    verdict.allowed = false;

    await expect(
      authService.requestPasswordReset({ email: "alice@example.com" }),
    ).resolves.toBeUndefined();
    expect(sentEmails).toHaveLength(0);
  });
});

